from collections import defaultdict

def canConvertString(s: str, t: str, k: int) -> bool:
    if len(s) != len(t):
        return False

    shift_counts = defaultdict(int)

    for c1, c2 in zip(s, t):
        diff = (ord(c2) - ord(c1)) % 26
        if diff == 0:
            continue

        current_count = shift_counts[diff]
        required_move = diff + current_count * 26

        if required_move > k:
            return False

        shift_counts[diff] += 1

    return True
